public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType == null || targetType == null) {
        throw new IllegalArgumentException("Neither genericType nor targetType can be null");
    }

    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();

    Class<?>[] resolvedArguments = new Class<?>[actualTypeArguments.length];
    for (int i = 0; i < actualTypeArguments.length; i++) {
        Type typeArgument = actualTypeArguments[i];
        if (typeArgument instanceof Class) {
            resolvedArguments[i] = (Class<?>) typeArgument;
        } else if (typeArgument instanceof TypeVariable) {
            TypeVariable<?> typeVariable = (TypeVariable<?>) typeArgument;
            resolvedArguments[i] = resolveTypeVariable(typeVariable, targetType);
        } else {
            return null; // Cannot resolve other types like WildcardType, GenericArrayType, etc.
        }
    }

    return resolvedArguments;
}

private static Class<?> resolveTypeVariable(TypeVariable<?> typeVariable, Class<?> targetType) {
    Type[] bounds = typeVariable.getBounds();
    if (bounds.length == 0 || !(bounds[0] instanceof Class)) {
        return null; // No class bound found
    }

    Class<?> boundClass = (Class<?>) bounds[0];
    if (boundClass.isInterface()) {
        for (Type interfaceType : targetType.getGenericInterfaces()) {
            if (interfaceType instanceof ParameterizedType) {
                ParameterizedType parameterizedType = (ParameterizedType) interfaceType;
                if (parameterizedType.getRawType().equals(boundClass)) {
                    return resolveTypeVariableFromBounds(typeVariable, parameterizedType);
                }
            }
        }
    } else {
        Class<?> superClass = targetType.getSuperclass();
        while (superClass != null) {
            if (superClass.equals(boundClass)) {
                Type genericSuperclass = targetType.getGenericSuperclass();
                if (genericSuperclass instanceof ParameterizedType) {
                    ParameterizedType parameterizedType = (ParameterizedType) genericSuperclass;
                    return resolveTypeVariableFromBounds(typeVariable, parameterizedType);
                }
            }
            superClass = superClass.getSuperclass();
        }
    }

    return null; // Type variable could not be resolved
}

private static Class<?> resolveTypeVariableFromBounds(TypeVariable<?> typeVariable, ParameterizedType parameterizedType) {
    TypeVariable<?>[] typeVariables = ((Class<?>) parameterizedType.getRawType()).getTypeParameters();
    Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();

    for (int i = 0; i < typeVariables.length; i++) {
        if (typeVariable.equals(typeVariables[i])) {
            Type actualTypeArgument = actualTypeArguments[i];
            if (actualTypeArgument instanceof Class) {
                return (Class<?>) actualTypeArgument;
            }
        }
    }

    return null; // Type variable could not be resolved from bounds
}

