static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be greater than 0");
    }
    if (timeBucket < 10000000 || timeBucket > 99991231) {
        throw new IllegalArgumentException("timeBucket must be a valid date in the format YYYYMMDD");
    }

    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket % 10000) / 100);
    int day = (int) (timeBucket % 100);

    // Calculate the day of the year
    int[] daysInMonth = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    if (year % 4 == 0 && (year % 100 != 0 || year % 400 == 0)) {
        daysInMonth[1] = 29; // Leap year
    }

    int dayOfYear = 0;
    for (int i = 0; i < month - 1; i++) {
        dayOfYear += daysInMonth[i];
    }
    dayOfYear += day;

    // Calculate the new day of the year based on dayStep
    int newDayOfYear = (dayOfYear / dayStep) * dayStep;

    // Convert the new day of the year back to day, month, year
    int newDay = 0;
    int newMonth = 0;
    for (int i = 0; i < 12; i++) {
        if (newDayOfYear <= daysInMonth[i]) {
            newDay = newDayOfYear;
            newMonth = i + 1;
            break;
        }
        newDayOfYear -= daysInMonth[i];
    }

    // Format the new time bucket
    return year * 10000L + newMonth * 100L + newDay;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IllegalArgumentException("Index and length must be non-negative and index + length must be less than or equal to the length of the string");
    }

    int size = 0;
    for (int i = index; i < index + len; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(ch)) {
            if (i + 1 < index + len && Character.isLowSurrogate(str.charAt(i + 1))) {
                size += 4; // surrogate pair
                i++; // skip the low surrogate
            } else {
                throw new IllegalArgumentException("Invalid surrogate pair in string");
            }
        } else {
            size += 3;
        }
    }
    return size;
}

