public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (session == null) {
        throw new IllegalArgumentException("WriteSession cannot be null");
    }
    if (lb == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    try {
        int length = str.length();
        int utf8Length = 0;
        for (int i = 0; i < length; i++) {
            char c = str.charAt(i);
            if (c < 0x80) {
                utf8Length++;
            } else if (c < 0x800) {
                utf8Length += 2;
            } else if (Character.isSurrogate(c)) {
                if (i + 1 < length) {
                    char nextChar = str.charAt(i + 1);
                    if (Character.isSurrogatePair(c, nextChar)) {
                        utf8Length += 4;
                        i++; // Skip the next character as it is part of the surrogate pair
                    } else {
                        throw new IllegalArgumentException("Invalid surrogate pair in input string");
                    }
                } else {
                    throw new IllegalArgumentException("Unpaired surrogate character in input string");
                }
            } else {
                utf8Length += 3;
            }
        }

        byte[] utf8Bytes = new byte[utf8Length];
        int index = 0;
        for (int i = 0; i < length; i++) {
            char c = str.charAt(i);
            if (c < 0x80) {
                utf8Bytes[index++] = (byte) c;
            } else if (c < 0x800) {
                utf8Bytes[index++] = (byte) (0xc0 | (c >> 6));
                utf8Bytes[index++] = (byte) (0x80 | (c & 0x3f));
            } else if (Character.isSurrogate(c)) {
                if (i + 1 < length) {
                    char nextChar = str.charAt(i + 1);
                    if (Character.isSurrogatePair(c, nextChar)) {
                        int codePoint = Character.toCodePoint(c, nextChar);
                        utf8Bytes[index++] = (byte) (0xf0 | (codePoint >> 18));
                        utf8Bytes[index++] = (byte) (0x80 | ((codePoint >> 12) & 0x3f));
                        utf8Bytes[index++] = (byte) (0x80 | ((codePoint >> 6) & 0x3f));
                        utf8Bytes[index++] = (byte) (0x80 | (codePoint & 0x3f));
                        i++; // Skip the next character as it is part of the surrogate pair
                    }
                }
            } else {
                utf8Bytes[index++] = (byte) (0xe0 | (c >> 12));
                utf8Bytes[index++] = (byte) (0x80 | ((c >> 6) & 0x3f));
                utf8Bytes[index++] = (byte) (0x80 | (c & 0x3f));
            }
        }

        return session.writeBytes(utf8Bytes, lb);
    } catch (Exception e) {
        throw new RuntimeException("Error writing UTF-8 bytes to LinkedBuffer", e);
    }
}

