private void pop(final String descriptor) {
    if (descriptor == null) {
        throw new IllegalArgumentException("Descriptor cannot be null");
    }

    // Check if the descriptor is a method descriptor
    if (descriptor.startsWith("(")) {
        int endIndex = descriptor.indexOf(')');
        if (endIndex == -1) {
            throw new IllegalArgumentException("Invalid method descriptor: missing ')'");
        }

        String argumentTypes = descriptor.substring(1, endIndex);
        int index = 0;
        while (index < argumentTypes.length()) {
            char type = argumentTypes.charAt(index);
            switch (type) {
                case 'B': // byte
                case 'C': // char
                case 'D': // double
                case 'F': // float
                case 'I': // int
                case 'S': // short
                case 'Z': // boolean
                    index++;
                    break;
                case 'J': // long
                    index += 2; // long occupies two slots
                    break;
                case 'L': // object
                case '[': // array
                    index = argumentTypes.indexOf(';', index) + 1;
                    if (index == 0) {
                        throw new IllegalArgumentException("Invalid descriptor: missing ';'");
                    }
                    break;
                default:
                    throw new IllegalArgumentException("Invalid descriptor character: " + type);
            }
        }
    } else {
        // Handle field descriptor
        switch (descriptor) {
            case "B": // byte
            case "C": // char
            case "D": // double
            case "F": // float
            case "I": // int
            case "S": // short
            case "Z": // boolean
                break;
            case "J": // long
                // long occupies two slots, but we only pop one here
                break;
            case "L": // object
            case "[": // array
                if (!descriptor.endsWith(";")) {
                    throw new IllegalArgumentException("Invalid descriptor: missing ';'");
                }
                break;
            default:
                throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
        }
    }
}

