    if (desiredCapacity < 2) {
        throw new IllegalArgumentException("desiredCapacity must be >= 2");
    }

    int candidate = desiredCapacity;
    while (!isPrime(candidate)) {
        candidate++;
    }

    if (desiredCapacity >= 1000 && candidate > desiredCapacity * 1.11) {
        candidate = desiredCapacity;
        while (!isPrime(candidate)) {
            candidate--;
            if (candidate < desiredCapacity * 0.89) {
                throw new RuntimeException("No suitable prime found within 11% of desiredCapacity");
            }
        }
    }

    return candidate;
}

private static boolean isPrime(int number) {
    if (number <= 1) {
        return false;
    }
    if (number <= 3) {
        return true;
    }
    if (number % 2 == 0 || number % 3 == 0) {
        return false;
    }
    for (int i = 5; i * i <= number; i += 6) {
        if (number % i == 0 || number % (i + 2) == 0) {
            return false;
        }
    }
    return true;
}

