private void pop(final String descriptor) {
    if (descriptor == null) {
        throw new IllegalArgumentException("Descriptor cannot be null");
    }

    // Check if the descriptor is a method descriptor
    if (descriptor.startsWith("(")) {
        int endIndex = descriptor.indexOf(')');
        if (endIndex == -1) {
            throw new IllegalArgumentException("Invalid method descriptor: missing ')'");
        }

        String argumentTypes = descriptor.substring(1, endIndex);
        int index = 0;
        while (index < argumentTypes.length()) {
            char typeChar = argumentTypes.charAt(index);
            switch (typeChar) {
                case 'B': // byte
                case 'C': // char
                case 'D': // double
                case 'F': // float
                case 'I': // int
                case 'S': // short
                case 'Z': // boolean
                    index++;
                    break;
                case 'J': // long
                    index += 2; // long occupies two slots
                    break;
                case 'L': // object
                    int semicolonIndex = argumentTypes.indexOf(';', index);
                    if (semicolonIndex == -1) {
                        throw new IllegalArgumentException("Invalid object descriptor: missing ';'");
                    }
                    index = semicolonIndex + 1;
                    break;
                case '[': // array
                    index++;
                    // Continue to parse the array type
                    break;
                default:
                    throw new IllegalArgumentException("Invalid type character in descriptor: " + typeChar);
            }
        }
    } else {
        // Handle field descriptor
        switch (descriptor.charAt(0)) {
            case 'B': // byte
            case 'C': // char
            case 'D': // double
            case 'F': // float
            case 'I': // int
            case 'S': // short
            case 'Z': // boolean
                break;
            case 'J': // long
                // long occupies two slots
                break;
            case 'L': // object
                if (descriptor.indexOf(';') != descriptor.length() - 1) {
                    throw new IllegalArgumentException("Invalid object descriptor: missing ';'");
                }
                break;
            case '[': // array
                // Array type is valid
                break;
            default:
                throw new IllegalArgumentException("Invalid type character in descriptor: " + descriptor.charAt(0));
        }
    }
}

